import{G as e,W as t,n,rt as r}from"./chunks/framework.CJ3GlOSn.js";var i=JSON.parse(`{"title":"Sms","description":"","frontmatter":{},"headers":[],"relativePath":"03-developer/models/sms.md","filePath":"03-developer/models/sms.md"}`),a={name:`03-developer/models/sms.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="sms" tabindex="-1">Sms <a class="header-anchor" href="#sms" aria-label="Permalink to “Sms”">​</a></h1><p>The <code>Sms</code> model is used to log system SMS messages. This table makes it possible to review and track messages, including those related to authentication, messages sent to users, and messages associated with system events such as order placement or confirmation.</p><p>This model currently has no dedicated methods, and its data is stored solely for record-keeping and potential review. SMS logs are not currently displayed in the admin panel, but the information is available when needed to investigate sensitive events.</p><h2 id="data-structure" tabindex="-1">Data structure <a class="header-anchor" href="#data-structure" aria-label="Permalink to “Data structure”">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Nullable</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>Unique record ID</td></tr><tr><td><code>mobile</code></td><td>VARCHAR(15)</td><td>No</td><td>Mobile number for which the SMS was logged</td></tr><tr><td><code>text</code></td><td>TEXT</td><td>No</td><td>SMS text</td></tr><tr><td><code>code</code></td><td>VARCHAR(50)</td><td>Yes</td><td>Code associated with the SMS; for authentication messages, a separate code is stored in this field</td></tr><tr><td><code>ip</code></td><td>VARCHAR(45)</td><td>No</td><td>IP address associated with the request or SMS-sending process</td></tr><tr><td><code>user</code></td><td>ENUM(&#39;user&#39;, &#39;system&#39;)</td><td>No</td><td>SMS category based on its origin: <code>user</code> or <code>system</code></td></tr><tr><td><code>created_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Log creation time</td></tr><tr><td><code>updated_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Time of last update</td></tr></tbody></table><h2 id="meaning-of-the-user-field" tabindex="-1">Meaning of the <code>user</code> field <a class="header-anchor" href="#meaning-of-the-user-field" aria-label="Permalink to “Meaning of the user field”">​</a></h2><p>The <code>user</code> field indicates which category the SMS belongs to:</p><ul><li><code>user</code>: Messages associated with a user request.</li><li><code>system</code>: Messages associated with system processes; for example, notifications about order placement or confirmation. This category may also include messages related to an administrator or other parts of the system.</li></ul><p>This field categorizes the SMS; it does not, by itself, identify the person who sent or received it.</p><h2 id="tracking-and-troubleshooting" tabindex="-1">Tracking and troubleshooting <a class="header-anchor" href="#tracking-and-troubleshooting" aria-label="Permalink to “Tracking and troubleshooting”">​</a></h2><p>The information recorded in this table can be useful when investigating issues or sensitive events. For example, the mobile number, SMS text, log time, and IP address can help review message history.</p><p>In addition to being recorded in the <code>sms</code> table, the IP address is stored as supplementary information through the <code>GuestLog</code> mechanism to allow more detailed tracking when needed.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to “Notes”">​</a></h2><ul><li>This table serves as an SMS log; displaying it in the admin panel has not been implemented.</li><li>The <code>code</code> field is intended to store codes associated with SMS messages, including authentication codes.</li><li>The presence of a record in this table does not, by itself, prove that the SMS was delivered to the destination phone. The table stores the recorded SMS history.</li></ul>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};